Определите наибольшее значение входной переменной k, при котором программа выдаёт тот же ответ, что и при входном значении k = 45.
Для Вашего удобства программа приведена на пяти языках программирования.

Бейсик

DIM K, I AS LONG

INPUT K

I = 1

WHILE F(I) < G(K)

I = I + 1

WEND

PRINT I

FUNCTION F(N)
F = N * N * N

END FUNCTION

FUNCTION G(N)
G = 2 * N + 5

END FUNCTION

Python

def F(n):

return n*n*n

def G(n):

return 2 * n + 5

k = int(input())

i = 1

while F(i) < G(k):

i+=1

print (i)

