const n = 4;

var i, x: integer;

var minimum, count: integer;

begin

count := 0;

minimum := 0;

for i := 1 to n do

begin

read(x);

if x mod 5 = 0 then

begin

count := count + 1;

if x > minimum then

minimum := x

end

end;

if count > 0 then

begin

writeln(count);

writeln(minimum)

end

else

